SELECT id, store_name, city, opened_date, FIRST_VALUE(sqft, TRUE) OVER (ORDER BY opened_date, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS first_known_sqft, AVG(sqft) OVER (PARTITION BY city) AS city_avg_sqft, NTILE(3) OVER (PARTITION BY city, region ORDER BY sqft, id) AS sqft_bucket, LAST_VALUE(sqft) IGNORE NULLS OVER (PARTITION BY city, region ORDER BY sqft, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS last_known_sqft, ROUND(sqft / SUM(sqft) OVER (PARTITION BY region), 4) AS sqft_share FROM stores
